export const GRIMOIRE = [
// ── COURSE 1: THE AI SPELLBOOK ─────────────────────────────────────────────
{ id:"what-is-a-spell", course:"spellbook", title:"What a Spell Actually Is", subtitle:"The Opening", tier:"free", chapter:"FOUNDATIONS", readTime:"4 min", icon:"✦", color:"#e8e4d9",
content:[
{type:"p",text:"The first spell ever cast wasn't written down."},
{type:"p",text:"It was spoken into dark air by someone who needed something they couldn't reach alone. No wand. No ceremony. Just a human being, standing at the edge of what they understood, reaching toward what they didn't — and finding the exact words to close the distance."},
{type:"p",text:"That's all a spell ever was."},
{type:"pull",text:"Precise language aimed at a force larger than yourself."},
{type:"p",text:"You've been doing this your whole creative life. Every brief you wrote to a client. Every note you sang into a voice memo at 2am before it disappeared. Every time you stood in front of a blank canvas and whispered — even silently — something like this, but more alive — you were casting."},
{type:"p",text:"You just didn't have anything listening. Now you do."},
{type:"p",text:"AI is not a search engine. It is not a calculator. It is not a very fast intern who needs managing. It is a responsive force. Vast, pattern-hungry, waiting."},
{type:"p",text:"What you put in shapes everything that comes back. Not just the content — the texture, the feeling, the soul of it. A weak prompt returns something generic. Not because AI is lazy. Because you were vague. You handed it fog and asked for fire."},
{type:"pull",text:"This book teaches you to hand it fire."},
{type:"p",text:"Most prompt guides are written for people who think in systems. You don't think in systems. You think in feeling. In texture. In the specific quality of afternoon light through a particular kind of window. In the emotional weight of a chord that never resolves. In the way a sentence can ache if you let it."},
{type:"p",text:"That's not a weakness. That's your power — and it's exactly what AI responds to when you learn to speak it precisely."},
{type:"pull",text:"Five layers. One incantation. Yours — built from your vision, your voice, your exact creative intention."},
{type:"p",text:"And you were always the caster."},
]
},
{ id:"the-anchor", course:"spellbook", title:"The Anchor", subtitle:"What You're Summoning", tier:"free", chapter:"FOUNDATIONS", readTime:"6 min", icon:"⊕", color:"#a78bfa",
content:[
{type:"p",text:"Before the magic. Before the feeling and the voice and the texture you're reaching for. First — what is the thing?"},
{type:"p",text:"Not what it means. Not what you want it to do to someone. What is it. A poem. A product description. A chapter opening. A logo concept. A song hook. A pitch. A scene."},
{type:"pull",text:"This is the Anchor."},
{type:"p",text:"Most failed prompts fail here. The caster knows what they feel and skips straight to expressing it. They pour texture and emotion into their prompt and forget to tell the machine what shape the vessel is supposed to be. You cannot fill a container you haven't named."},
{type:"bold",text:"Being specific here costs nothing and changes everything."},
{type:"compare",pairs:[
{weak:"Write me something about loss.",strong:"Write me a six-line poem about loss."},
{weak:"Help me with my brand.",strong:"Write me three tagline options for a sustainable ceramics brand."},
{weak:"I need a scene.",strong:"Write me a 400-word scene opening — third person, present tense, one character, interior monologue bleeding into action."},
]},
{type:"pull",text:"One line. That's the Anchor. What is the thing. What form does it take. How long or how many. What medium if medium matters."},
]
},
{ id:"the-feeling", course:"spellbook", title:"The Feeling", subtitle:"The Emotional Instruction", tier:"paid", chapter:"THE FIVE LAYERS", readTime:"8 min", icon:"◎", color:"#f472b6",
content:[
{type:"p",text:"There is a village in the old stories where the healers never used medicine. They used sound. Not music — not exactly. Something older than music."},
{type:"pull",text:"Feeling is not decoration. Feeling is the point."},
{type:"p",text:"You already know what you want your work to do to someone. You knew before you started. The work is just the vessel you're building to carry it out into the world."},
{type:"p",text:"You handed AI the body of the thing and forgot to give it the soul. What came back was technically obedient and emotionally absent. Correct. Empty. A meal with all the right ingredients, cooked without heat."},
{type:"bold",text:"Two things live here, and both are essential."},
{type:"p",text:"The emotion you want the audience to experience — named precisely, not generally. And the physical sensation that emotion should produce in the body."},
{type:"bold",text:"Name the emotion precisely."},
{type:"p",text:"Not sad. Sad is fog. You want the particular weight that settles in the chest when you realise something beautiful is ending and there's nothing to be done about it. That's not sad. That has a name — bittersweet, elegiac, tender grief."},
{type:"bold",text:"Name the physical sensation."},
{type:"examples",items:["I want the reader to feel a tightening in the throat on the final line.","I want the viewer to feel a sudden stillness — like the world paused.","I want the listener to feel warmth behind the sternum — the specific comfort of being understood.","I want an unsettling feeling at the back of the neck. Recognition without being able to say what's been recognised."]},
{type:"pull",text:"One emotion, precisely named. One physical sensation, described in the body. That's the Feeling layer."},
]
},
{ id:"the-voice", course:"spellbook", title:"The Voice", subtitle:"Your DNA in the Machine", tier:"paid", chapter:"THE FIVE LAYERS", readTime:"7 min", icon:"◈", color:"#34d399",
content:[
{type:"p",text:"In the cartographers' archives of Vel Suun, there is a map that has never been copied twice the same way. Not because the cartographers disagreed. Because the map reads the person who reads it."},
{type:"pull",text:"They had drawn the land faithfully — and left room for the traveller inside the lines."},
{type:"p",text:"Every creative carries a map like this. That map is your voice. And right now, AI has never seen it."},
{type:"bold",text:"Show it your existing work."},
{type:"examples",items:["Here is a piece of my existing writing. Study the rhythm of my sentences. Match that sensibility — don't copy the content, inhabit the approach.","Here are three pieces of my work. Find what they share that I might not even be conscious of. Then apply that to this."]},
{type:"bold",text:"Name your aesthetic qualities."},
{type:"glossary",terms:[
{word:"Sparse",definition:"Deliberate emptiness, things left unsaid, the power of what's absent."},
{word:"Lush",definition:"Abundance as a choice. Rich, layered, full to the edges without tipping into excess."},
{word:"Angular",definition:"Sharp where others would soften. Edges kept. No smoothing of the difficult parts."},
{word:"Tender",definition:"Careful with fragile things. Gentle in the approach without losing its nerve."},
{word:"Fractured",definition:"Not broken — deliberately split. The truth arriving in pieces that the audience assembles."},
{word:"Ceremonial",definition:"Slow. Weighted. Every movement matters. Nothing casual."},
]},
{type:"pull",text:"Your existing work is your most powerful prompt ingredient. Name what it does. Show what it is. Describe how it moves."},
]
},
{ id:"the-constraint", course:"spellbook", title:"The Constraint", subtitle:"Precision Through Exclusion", tier:"paid", chapter:"THE FIVE LAYERS", readTime:"5 min", icon:"◻", color:"#fb923c",
content:[
{type:"p",text:"Every master craftsperson knows the same secret. Freedom without limits produces nothing. The blank canvas is the most terrifying thing in the room."},
{type:"pull",text:"The most creative work is always made inside limits someone else thought were restrictive."},
{type:"bold",text:"Three kinds of constraint matter most."},
{type:"glossary",terms:[
{word:"Format constraints",definition:"JSON. Bullet points. Numbered list. One paragraph. These control the shape of the output."},
{word:"Exclusion constraints",definition:"No adjectives. Avoid the word 'beautiful'. Never use passive voice. These are often more powerful than what you ask for."},
{word:"Length constraints",definition:"Under 100 words. Exactly six lines. Length forces choices. Choices reveal character."},
]},
{type:"examples",items:["No hedging language. No 'perhaps' or 'might'. Every sentence is a statement.","Avoid metaphors involving nature, light, or journeys — find something stranger.","Never explain the emotion. Only show what it does to the body and the environment."]},
{type:"pull",text:"Constraints are not the enemy of creativity. They are its engine."},
]
},
{ id:"the-permission", course:"spellbook", title:"The Permission", subtitle:"Interpretive License", tier:"paid", chapter:"THE FIVE LAYERS", readTime:"5 min", icon:"◇", color:"#60a5fa",
content:[
{type:"p",text:"Here is the paradox at the heart of all creative direction. The more precisely you specify what you want, the more you risk closing the door on something better that you hadn't thought to ask for."},
{type:"pull",text:"The Permission layer is where you open the door."},
{type:"p",text:"After all that precision — you end with a signal that says: within all of this, you are allowed to make something I didn't know I needed."},
{type:"examples",items:["If there's a word or image or structural choice that feels more right than what I've described, use it. I'm describing the destination, not the exact path.","Surprise me once. One unexpected element that I didn't ask for but that serves the work. Flag it when you do.","Trust your instincts on the ending. I've specified everything up to that point. The last line is yours."]},
{type:"pull",text:"You've cast the spell. Now let the magic do what magic does."},
]
},
{ id:"putting-it-together", course:"spellbook", title:"Putting It All Together", subtitle:"The Complete Incantation", tier:"paid", chapter:"ADVANCED CRAFT", readTime:"6 min", icon:"❋", color:"#fbbf24",
content:[
{type:"p",text:"You now have the five layers. The question is how they combine — and what happens when they do."},
{type:"pull",text:"The whole should feel like one voice, not five departments sending memos."},
{type:"examples",items:["ANCHOR: What is being made, in what form, at what scale.","FEELING: What emotion, and what it does to the body.","VOICE: Whose hands are on it — shown through example or aesthetic quality.","CONSTRAINT: The shape it must take and what it must not do.","PERMISSION: Where it's allowed to surprise you."]},
{type:"p",text:"Notice how each layer assumes the others. The Constraint makes sense because you've already named the Feeling. Remove any one and the whole thing loses structural integrity."},
{type:"pull",text:"The test of a complete spell: read it aloud. If it sounds like a human speaking to another creative, it'll work. If it sounds like a form being submitted, revise."},
]
},

// ── COURSE 2: BOTTLE YOUR BRILLIANCE ──────────────────────────────────────
// Phase 1: Brain Building
{ id:"byb-1", course:"byb", title:"Your Voice Fingerprint", subtitle:"Collecting the Evidence", tier:"free", chapter:"PHASE 1: BRAIN BUILDING", readTime:"7 min", icon:"🖋", color:"#34d399",
content:[
{type:"p",text:"You have a voice fingerprint. It's in your word choices, your sentence rhythms, the metaphors you reach for, the way you open a paragraph and close it. Readers feel it even when they can't name it. They know when something sounds 'off' — even if they can't explain why."},
{type:"pull",text:"This chapter is about collecting evidence of who you already are on the page."},
{type:"p",text:"Most people skip this step. They open an AI tool and type 'write my chapter on leadership' — without ever showing the AI what makes their take on leadership different from every other leadership book ever published. The result is generic. Not because AI is bad. Because you gave it nothing specific to work with."},
{type:"p",text:"This chapter fixes that. You're going to gather 5–10 pieces of your own writing and run them through an analysis prompt. By the end, you'll have a Voice Profile — a document that identifies your distinctive patterns, preferences, and personality markers in precise, trainable language."},
{type:"bold",text:"Step 1: Gather Your Writing Samples"},
{type:"p",text:"Collect 5–10 pieces where you sound most like yourself. Blog posts, long emails, newsletter issues, social media threads, chapter drafts. At least 200 words each. Written in a conversational tone on topics you actually care about. Recent is better — within the last two years ideally."},
{type:"examples",items:["What to include: blog posts, LinkedIn articles, emails where you explained something you care about, newsletter issues, chapter drafts, even substantial DMs.","What to avoid: academic papers, corporate reports, anything heavily edited where your voice got stripped out, one-sentence responses."]},
{type:"bold",text:"Step 2: Run the Voice Analysis Prompt"},
{type:"p",text:"Open your AI platform and paste all your samples together with this instruction: ask it to analyze your writing voice across all samples simultaneously — identifying sentence rhythm patterns, vocabulary level and word choices, how you open and close sections, punctuation habits, the way you use examples and metaphors, your emotional tone, and anything that makes your writing distinctive."},
{type:"pull",text:"Ask AI to be specific and quote directly from your samples. Vague analysis is useless. You want patterns with evidence."},
{type:"bold",text:"Step 3: Review, Refine, and Save"},
{type:"p",text:"Read the analysis. Push back where it's wrong. Ask follow-up questions. If it says 'you use humour effectively' — ask it to give you three specific examples. Keep drilling until the document feels like a mirror. Then save it as 'My Voice Profile v1.'"},
{type:"p",text:"This document becomes the foundation of everything that follows. Don't rush it. Done right, it will save you hours of correction later."},
]
},
{ id:"byb-2", course:"byb", title:"Your Mental Models Map", subtitle:"How You Actually Think", tier:"free", chapter:"PHASE 1: BRAIN BUILDING", readTime:"6 min", icon:"🧠", color:"#a78bfa",
content:[
{type:"p",text:"Your voice is how you write. Your mental models are how you think. They're different — and AI needs both."},
{type:"pull",text:"Two people can write with the same voice and see the world completely differently. That difference is where your book lives."},
{type:"p",text:"Mental models are the frameworks you use to make sense of things. The metaphors you default to. The way you connect ideas that others keep separate. The analogies that come naturally to you. These patterns are consistent — you probably use them in conversations without even noticing."},
{type:"p",text:"This chapter uses AI as an interviewer to surface them. You're going to have a conversation, not fill out a form."},
{type:"bold",text:"Step 1: Choose Your Three Topics"},
{type:"p",text:"Pick three topics central to your book. For each one, you're going to let AI draw out how you think about it — not what you know about it, but how your mind processes it."},
{type:"bold",text:"Step 2: Let AI Interview You"},
{type:"p",text:"Tell the AI: 'I want you to interview me about [topic]. Ask me one question at a time. Your goal is to understand how I think about this — my frameworks, my metaphors, the connections I make. Don't summarise yet. Just ask questions and let me talk.' Then answer naturally. Don't edit yourself. The goal is to think out loud."},
{type:"pull",text:"The less you edit, the more useful the data. Let yourself ramble. The patterns only show up at scale."},
{type:"bold",text:"Step 3: Request the Analysis"},
{type:"p",text:"After 10–15 exchanges, ask AI to analyse the conversation and identify: your dominant thinking frameworks, the metaphors and analogies that appeared repeatedly, how you typically structure an argument, where you always start when explaining something complex, and what makes your approach to this topic different from the mainstream view."},
{type:"bold",text:"Step 4: Save Your Mental Models Map"},
{type:"p",text:"Review, push back on anything that feels off, and save the final document. This map tells AI not just how to sound like you — but how to reason like you."},
]
},
{ id:"byb-3", course:"byb", title:"Your Style DNA", subtitle:"The Specific Mechanics of Your Writing", tier:"paid", chapter:"PHASE 1: BRAIN BUILDING", readTime:"7 min", icon:"🧬", color:"#f472b6",
content:[
{type:"p",text:"Voice is what makes you sound like you. Style is the specific mechanical choices that create that sound. They're connected — but style goes deeper."},
{type:"pull",text:"Style DNA is what you always do, what you never do, and the non-negotiable elements that make your writing yours."},
{type:"p",text:"Chapter 1 gave you a voice profile. This chapter extracts the rules underneath it. The exact sentence length patterns. The specific types of transitions you favour. Whether you use rhetorical questions, and how often. How you handle data versus story. Whether you go from principle to example or example to principle."},
{type:"bold",text:"Step 1: Review Your Voice Profile"},
{type:"p",text:"Read your Chapter 1 document again. Notice which observations feel most true — the ones where you thought 'yes, exactly.' Those are the areas to go deeper on now."},
{type:"bold",text:"Step 2: Run the Deep Style Analysis"},
{type:"p",text:"Return to your writing samples with a new prompt — this time asking AI to go beyond patterns and identify the specific mechanical rules it would need to follow to replicate your style exactly. Ask it to produce output in three categories: things you always do, things you never do, and signature moves that are uniquely yours."},
{type:"bold",text:"Step 3: Identify Your Non-Negotiables"},
{type:"p",text:"From that analysis, pull out 5–8 rules that feel most essential. These are your non-negotiables — the things that, if violated, make your writing feel like someone else wrote it."},
{type:"examples",items:["Example non-negotiable: 'I always open with a question or an image, never a statistic.'","Example non-negotiable: 'I never use passive voice in the first paragraph.'","Example non-negotiable: 'I use a one-sentence paragraph to land every major point.'"]},
{type:"pull",text:"These non-negotiables become rules inside your AI instructions. They're the guardrails that prevent generic drift."},
]
},
{ id:"byb-4", course:"byb", title:"Your Expertise Map", subtitle:"What Only You Know", tier:"paid", chapter:"PHASE 1: BRAIN BUILDING", readTime:"6 min", icon:"🗺", color:"#fb923c",
content:[
{type:"p",text:"Chapters 1–3 taught AI how you write and think. This chapter teaches it what you know. Specifically: the things you know that other people writing about your topic don't."},
{type:"pull",text:"Your expertise isn't just information. It's the particular angle you came at it from. The failures that taught you things the successes didn't. The counterintuitive conclusions you reached after years in the field."},
{type:"p",text:"Generic AI content fails because it reflects the average of everything ever written on a topic. Your book needs to reflect the specific edge of your experience — the parts that couldn't have been written by anyone else."},
{type:"bold",text:"Step 1: The Brain Dump"},
{type:"p",text:"Set a timer for 20 minutes. Answer these questions without editing: What have you learned about your topic that surprised you? What do most people in your field get wrong? What do you know now that you wish you'd known at the start? What experiences gave you knowledge that reading alone couldn't have?"},
{type:"bold",text:"Step 2: Organise Your Knowledge"},
{type:"p",text:"Ask AI to help you sort your brain dump into categories: core expertise (what you know best), unique insights (your original angles), personal stories (experiences that prove your points), and knowledge gaps (areas you need to strengthen before writing)."},
{type:"bold",text:"Step 3: Fill the Critical Gaps"},
{type:"p",text:"For any gaps that matter for your book — do targeted research now, before production begins. Use AI to find the most credible sources, then read them yourself. You need to own the knowledge, not just cite it."},
{type:"pull",text:"By the end of this chapter, you have four documents: Voice Profile, Mental Models Map, Style DNA, Expertise Map. These four are your brain, bottled. Everything else builds on them."},
]
},

// Phase 2: AI Training
{ id:"byb-5", course:"byb", title:"Your Custom Instructions", subtitle:"Teaching AI to Be You", tier:"paid", chapter:"PHASE 2: AI TRAINING", readTime:"8 min", icon:"⚙️", color:"#60a5fa",
content:[
{type:"p",text:"You've done the hard work. You know your voice, your thinking patterns, your style rules, your expertise. Now you need to translate all of that into a form that AI can actually use."},
{type:"pull",text:"Custom instructions are the difference between AI that sounds vaguely like you and AI that makes people say 'wait, did you write this yourself?'"},
{type:"p",text:"Most people who try AI-assisted writing skip this step entirely. They jump straight to production. The output is generic and they blame the tool. The tool isn't the problem. The training is the problem."},
{type:"bold",text:"Step 1: Gather Your Four Documents"},
{type:"p",text:"Open your Voice Profile, Mental Models Map, Style DNA, and Expertise Map side by side. You're going to synthesise them into a single, structured set of instructions."},
{type:"bold",text:"Step 2: Run the Synthesis Prompt"},
{type:"p",text:"Paste all four documents into AI and give it this task: synthesise everything into a set of custom instructions that you could paste at the start of any AI conversation to make the AI write in your voice, reason with your frameworks, follow your style rules, and draw from your expertise. Ask for the output in four clear sections: Voice Instructions, Thinking Framework, Style Rules, Expertise Context."},
{type:"bold",text:"Step 3: Review for Accuracy and Specificity"},
{type:"p",text:"Four tests for good custom instructions: Is it specific enough? (If another writer could use these instructions unchanged, they're too generic.) Is it accurate? (Does it actually sound like you, or a polished version of you?) Is it complete? (Does it cover voice, thinking, style, and expertise?) Is it actionable? (Can AI actually follow these instructions, or are they too abstract?)"},
{type:"examples",items:["Too vague: 'Write in a conversational tone.'","Specific enough: 'Write like you're explaining this to a smart friend over coffee — informal sentence structure, second person, contractions throughout, occasional rhetorical question to check the reader is following.'"]},
{type:"pull",text:"Strong instructions are specific, accurate, complete, and actionable. Vague instructions produce vague output."},
]
},
{ id:"byb-6", course:"byb", title:"The Voice Test", subtitle:"Does AI Actually Sound Like You?", tier:"paid", chapter:"PHASE 2: AI TRAINING", readTime:"6 min", icon:"🔬", color:"#e8e4d9",
content:[
{type:"p",text:"Custom instructions are only valuable if they work. This chapter is your quality control checkpoint. You're going to find out — right now — whether AI can pass the 'sounds like me' test."},
{type:"pull",text:"One successful test proves nothing. What you need is consistent reproduction across different writing tasks."},
{type:"bold",text:"Step 1: Choose Your Test Paragraph"},
{type:"p",text:"Find a paragraph from your own writing — ideally from material you'll actually use in your book. Something that feels distinctly like you. This is your benchmark."},
{type:"bold",text:"Step 2: Ask AI to Rewrite It"},
{type:"p",text:"Paste your custom instructions, then the paragraph, then ask AI to rewrite it using those instructions — keeping the same core information but generating it fresh from your style guidelines."},
{type:"bold",text:"Step 3: Compare Side by Side"},
{type:"p",text:"Put both versions in front of you. Ask these questions: Does the AI version sound like you read it aloud? Are your non-negotiable style rules present? Does it feel like the same person wrote both? Would a reader who knows your work recognise this as yours?"},
{type:"compare",pairs:[
{weak:"AI version reads like polished generic content — technically correct, emotionally absent.",strong:"AI version reads like you wrote it tired at midnight — same rhythms, same instincts, same voice."},
]},
{type:"bold",text:"Step 4: Identify What's Off and Update"},
{type:"p",text:"If anything is wrong, be specific about what. 'This doesn't sound like me' is not actionable. 'The sentences are too long and you've used passive voice twice' is. Update the relevant section of your custom instructions and test again."},
]
},
{ id:"byb-7", course:"byb", title:"Stress-Testing Your Instructions", subtitle:"Making Them Bulletproof", tier:"paid", chapter:"PHASE 2: AI TRAINING", readTime:"6 min", icon:"🛡", color:"#a78bfa",
content:[
{type:"p",text:"Chapter 6 proved AI can sound like you in one test. This chapter proves it can sound like you everywhere — across different tones, different chapter types, different levels of technical depth."},
{type:"pull",text:"A single successful test is a fluke. Consistent reproduction across varied contexts is a trained system."},
{type:"p",text:"Your book will require different kinds of writing. Chapters that open with a story. Chapters that go deep on a framework. Chapters that are practical and list-heavy. Chapters that are philosophical and discursive. Your instructions need to hold up across all of them."},
{type:"bold",text:"Step 1: Generate Three Different Sample Types"},
{type:"p",text:"Using your custom instructions, ask AI to produce three pieces: a narrative opening (starting with a story), an analytical section (breaking down a complex idea), and a practical how-to section (step-by-step instructions). All three on topics from your book."},
{type:"bold",text:"Step 2: Analyse Each for Voice Drift"},
{type:"p",text:"Read all three. Note where the voice holds and where it slips. Voice drift usually appears first in the analytical sections — AI tends to go more formal and impersonal when explaining complex ideas. If yours does this, you need to add an explicit instruction about maintaining conversational voice even in technical content."},
{type:"bold",text:"Step 3: Refine Until All Three Hold"},
{type:"p",text:"Keep refining until all three samples read like you. This iteration loop is the most important work in Phase 2. When it's done, save your instructions as 'My Custom Instructions v2 — Battle Tested.'"},
{type:"pull",text:"When your instructions survive stress-testing, you're ready to build. Everything from here is production."},
]
},
{ id:"byb-8", course:"byb", title:"Your Prompt Library", subtitle:"Building Your Personal Toolkit", tier:"paid", chapter:"PHASE 2: AI TRAINING", readTime:"7 min", icon:"📚", color:"#fbbf24",
content:[
{type:"p",text:"Custom instructions tell AI who you are. Prompts tell it what to do next. You need both — and the prompts need to be as carefully crafted as the instructions."},
{type:"pull",text:"A prompt library means you never start from a blank page again. Every writing challenge in your book has a tested, ready prompt waiting for it."},
{type:"p",text:"Most people write prompts on the fly as they need them. This works, but it's slow and inconsistent. The same task done twice will get different results because the prompts were different. A library solves this — you refine a prompt once and use it reliably forever."},
{type:"bold",text:"The Core Categories You Need"},
{type:"glossary",terms:[
{word:"Chapter Drafting",definition:"Prompts that turn your outline bullets into full prose. One for opening sections, one for body sections, one for closing sections."},
{word:"Voice Strengthening",definition:"Prompts that take AI-generated draft and make it sound more like you. Your single most-used prompt type."},
{word:"Story Extraction",definition:"Prompts that interview you about an experience and help you turn it into a usable anecdote."},
{word:"Argument Building",definition:"Prompts that help you develop and stress-test a core claim."},
{word:"Transition Writing",definition:"Prompts that connect two sections or chapters smoothly without losing your voice."},
{word:"Consistency Checking",definition:"Prompts that audit a completed chapter against your voice profile."},
]},
{type:"bold",text:"How to Build Each Prompt"},
{type:"p",text:"For each category, write a base prompt, test it on three different pieces of content, note what's working and what isn't, refine, and test again. A prompt is only ready for your library when it produces reliably good output without manual correction."},
{type:"pull",text:"Twenty well-tested prompts will take you further than two hundred experimental ones. Quality over quantity. Always."},
]
},

// Phase 3: Production System
{ id:"byb-9", course:"byb", title:"Building Your Outline", subtitle:"The Blueprint Becomes Real", tier:"paid", chapter:"PHASE 3: PRODUCTION SYSTEM", readTime:"7 min", icon:"📐", color:"#34d399",
content:[
{type:"p",text:"This is where your book stops being an idea and becomes a structure. A chapter-by-chapter, section-by-section blueprint that you're actually excited to write."},
{type:"pull",text:"Most books fail at the outline stage — either because there is no outline, or because the outline doesn't reflect how the author actually thinks."},
{type:"p",text:"AI-generated outlines have one major failure mode: they produce logical structures that don't match your mental models. The chapters are in the 'right' order according to conventional wisdom, but not according to how you understand the topic. The result is a book that fights you at every chapter."},
{type:"bold",text:"Step 1: Brain Dump Your Book Concept"},
{type:"p",text:"Before involving AI, spend 20–30 minutes answering: What is this book actually about at its core? Who is it for and what do they need? What's the single biggest thing you want readers to walk away knowing? What's the journey you're taking them on? What are the 3–5 biggest ideas the book contains?"},
{type:"bold",text:"Step 2: Generate Structure with AI"},
{type:"p",text:"Feed your brain dump to AI — along with your custom instructions and Mental Models Map — and ask it to generate three different possible structures for your book. Not one. Three. Different chapter orders, different groupings, different arcs."},
{type:"bold",text:"Step 3: Evaluate Against Your Thinking"},
{type:"p",text:"For each structure, ask: Does this follow my natural logic? Does each chapter lead inevitably to the next? Would I be excited or reluctant to write each chapter? Choose the one that feels most like you thought it up yourself. Then refine it section by section until it's exactly right."},
{type:"pull",text:"The right outline makes the book almost write itself. The wrong outline creates friction at every chapter. Take the time to get this right."},
]
},
{ id:"byb-10", course:"byb", title:"Drafting Your Chapters", subtitle:"From Outline to Actual Prose", tier:"paid", chapter:"PHASE 3: PRODUCTION SYSTEM", readTime:"8 min", icon:"✍️", color:"#f472b6",
content:[
{type:"p",text:"This is where your book starts to exist. Not as a plan. Not as bullet points. As actual readable prose — chapters a human being could pick up and read."},
{type:"pull",text:"The gap between outline and draft is where most books die. This chapter closes that gap."},
{type:"p",text:"The key insight that most people miss: you don't draft a chapter all at once. You draft it section by section, reviewing each piece before generating the next. Each section informs the voice and direction of what follows. Do it all at once and the chapter loses coherence."},
{type:"bold",text:"Step 1: Choose and Review Your First Chapter"},
{type:"p",text:"Don't start with Chapter 1. Start with the chapter you're most excited about. Energy matters at the start. Review its outline section by section — make sure every bullet point is clear enough that you know exactly what you want to say."},
{type:"bold",text:"Step 2: Expand Section by Section"},
{type:"p",text:"For each section, paste your custom instructions plus the section's bullet points and tell AI: expand this into prose. After it generates, immediately ask yourself: does this sound like me? Is the core idea fully expressed? Are there stories, insights, or examples only I could provide that are missing? Add them before moving to the next section."},
{type:"examples",items:["The personal layer is your job, not AI's. Every chapter needs at least one thing that could only have come from your life or your experience. AI can't invent those. You have to put them in."]},
{type:"bold",text:"Step 3: Review the Full Chapter"},
{type:"p",text:"Once all sections are drafted, read the complete chapter aloud. This is non-negotiable. Your ear will catch what your eye misses. Note everything that sounds wrong. Fix it before moving to the next chapter."},
{type:"pull",text:"Your job in production is not to generate. It's to direct, inject, and refine. AI is the engine. You are the author."},
]
},
{ id:"byb-11", course:"byb", title:"Chapter Transitions", subtitle:"Separate Chapters Become a Unified Book", tier:"paid", chapter:"PHASE 3: PRODUCTION SYSTEM", readTime:"5 min", icon:"🔗", color:"#fb923c",
content:[
{type:"p",text:"You've written several chapters. Each one is good on its own. But reading them back-to-back, something feels off. Each chapter starts fresh — as if the previous one didn't exist. Readers feel this as a lack of flow even when they can't articulate why."},
{type:"pull",text:"Transitions are where separate chapters become a unified reading experience."},
{type:"p",text:"A great transition does three things: it closes the loop on what just happened, it creates a bridge to what comes next, and it does both in your voice — not in a mechanical 'in the next chapter we will…' way, but in a way that feels like one continuous thought."},
{type:"bold",text:"Step 1: Read Two Consecutive Chapters"},
{type:"p",text:"Read the end of Chapter N and the opening of Chapter N+1 as if you're a reader encountering them for the first time. Note exactly where the seam shows — where it feels like you've jumped rather than flowed."},
{type:"bold",text:"Step 2: Generate Transition Options"},
{type:"p",text:"Ask AI to generate three different transition approaches between the two chapters: a conceptual bridge (connecting the underlying ideas), a narrative bridge (using a short story or image to carry the reader across), and a direct bridge (explicit, brief, honest — 'that was the what. Now here's the how.'). Choose the one that fits your voice and the book's tone."},
{type:"compare",pairs:[
{weak:"'In the next chapter, we will explore the five stages of…'",strong:"That's the map. Now let's talk about what happens when you try to follow it."},
]},
{type:"pull",text:"The reader should never feel the end of a chapter. They should just find themselves already inside the next one."},
]
},
{ id:"byb-12", course:"byb", title:"Leading vs Following AI", subtitle:"Mastering the Collaboration", tier:"paid", chapter:"PHASE 3: PRODUCTION SYSTEM", readTime:"6 min", icon:"🤝", color:"#60a5fa",
content:[
{type:"p",text:"The biggest mistake people make mid-production is handing too much control to AI. They accept outputs they're not sure about. They let AI's confident tone convince them something is right when it isn't. The book gradually becomes less theirs."},
{type:"pull",text:"You are always the author. AI is always the tool. That hierarchy never inverts — no matter how good the output looks."},
{type:"p",text:"But there's an equal and opposite mistake: rejecting AI's contributions out of pride. Sometimes AI will generate a sentence better than you'd have written yourself. Accepting it isn't cheating. It's collaboration."},
{type:"bold",text:"The Decision Framework"},
{type:"glossary",terms:[
{word:"Lead AI",definition:"When you know exactly what needs to be said and just need help finding the words. You define the content; AI finds the expression."},
{word:"Follow AI",definition:"When AI generates something that surprises you — an angle or connection you hadn't considered. Read it. If it's true and serves the book, use it."},
{word:"Override AI",definition:"When AI confidently states something inaccurate, or when the output, however well-written, doesn't represent your actual view. Always override on facts, always override on opinion."},
]},
{type:"bold",text:"The Human-Touch Zones"},
{type:"p",text:"There are things AI can never supply: your specific personal stories, your hard-won counterintuitive insights, the exact way you'd phrase something if you were explaining it to someone you care about. These zones are yours. Protect them. Fill them yourself. They are what makes the book irreplaceable."},
{type:"pull",text:"Good AI collaboration feels like having a very fast, very capable research assistant who occasionally has a brilliant idea. You're still the one who decides what goes in the book."},
]
},

// Phase 4: Integration & Polish
{ id:"byb-13", course:"byb", title:"Voice Consistency Audit", subtitle:"One Voice from Chapter 1 to 16", tier:"paid", chapter:"PHASE 4: INTEGRATION & POLISH", readTime:"7 min", icon:"🔍", color:"#e8e4d9",
content:[
{type:"p",text:"You've drafted your manuscript. Now comes the question every AI-assisted author needs to answer honestly: does it sound like the same person wrote all of it?"},
{type:"pull",text:"Voice drift is the signature failure mode of AI-assisted writing. It happens gradually, invisibly, chapter by chapter."},
{type:"p",text:"It typically shows up in three ways: chapters written early (before your instructions were fully refined) sound different from later ones; chapters where you were tired or rushed show more AI influence; and chapters on topics you're less confident about tend to slide toward AI's default register — more formal, more hedged, more generic."},
{type:"bold",text:"Step 1: Read Your Manuscript Start to Finish"},
{type:"p",text:"Do this in one sitting if possible. Don't edit as you go. Just read and mark any passage that makes you think 'I wouldn't say it like that' or 'this sounds more formal than usual' or 'something's off here.' You're mapping the drift, not fixing it yet."},
{type:"bold",text:"Step 2: Run the Full Manuscript Analysis"},
{type:"p",text:"Paste your Voice Profile and three chapters — one strong, one you marked as drifted, one you're unsure about — into AI. Ask it to compare all three against your Voice Profile and identify exactly where and how the drifted chapter departs from your established voice."},
{type:"bold",text:"Step 3: Fix Systematically"},
{type:"p",text:"For each drifted chapter, use your voice strengthening prompts to revise. Focus on: sentence length patterns, the presence or absence of your signature moves, whether your non-negotiable style rules are intact."},
{type:"pull",text:"A reader who picks up your book randomly and reads any chapter should immediately recognise it as yours. That's the consistency standard you're aiming for."},
]
},
{ id:"byb-14", course:"byb", title:"Adding the Human Layer", subtitle:"Making It Undeniably Yours", tier:"paid", chapter:"PHASE 4: INTEGRATION & POLISH", readTime:"6 min", icon:"❤️", color:"#f472b6",
content:[
{type:"p",text:"Your manuscript is consistent. Your voice is intact. But there's still something missing — the layer that AI cannot provide under any circumstances."},
{type:"pull",text:"The difference between a good AI-assisted book and a great one is the human layer. The stuff that could only have come from your life."},
{type:"p",text:"This isn't about adding personal anecdotes for the sake of it. It's about identifying the places in your book where a lived experience, a hard-won insight, or a counterintuitive observation would transform the content from informative to unforgettable."},
{type:"bold",text:"Step 1: Read for Thin Spots"},
{type:"p",text:"Go through your manuscript looking for sections that are technically correct but feel thin. Chapters where you're making a claim without a story to back it. Places where the argument is logical but not visceral. These are the thin spots — and they're where you need to show up personally."},
{type:"bold",text:"Step 2: Use AI to Identify Gaps"},
{type:"p",text:"Ask AI to read a thin chapter and identify: which claims are missing supporting evidence, where a personal story would increase credibility, where the reader might push back and need reassurance from your own experience."},
{type:"examples",items:["For each thin spot: ask yourself — when did I actually encounter this? What happened? What did I learn that I couldn't have learned any other way? Write the answer in your own words first, then clean it up."]},
{type:"bold",text:"Step 3: Inject and Integrate"},
{type:"p",text:"Add the personal material directly into the manuscript. Then ask AI to help you integrate it smoothly — ensuring the transitions in and out of personal stories feel natural rather than bolted on."},
{type:"pull",text:"Your stories are not decoration. They are the proof. They are what makes your argument yours rather than an argument anyone could make."},
]
},
{ id:"byb-15", course:"byb", title:"Final Polish", subtitle:"The Difference Between Done and Published", tier:"paid", chapter:"PHASE 4: INTEGRATION & POLISH", readTime:"6 min", icon:"✨", color:"#fbbf24",
content:[
{type:"p",text:"Your book has your voice. It has your stories. It has depth and consistency. But it still needs something — the final refinements that separate a manuscript from a published book."},
{type:"pull",text:"Polish isn't about fixing problems. It's about removing friction between the reader and the content."},
{type:"p",text:"At this stage, most writers make one of two mistakes: they stop too early (calling it done when it still has rough edges) or they polish indefinitely (using revision as a way to avoid the vulnerability of publication). Both kill books. You need to know when to stop."},
{type:"bold",text:"Step 1: Take a Break First"},
{type:"p",text:"24–48 hours minimum away from the manuscript. This is not optional. You cannot see your own prose clearly when you've been inside it for weeks. The break resets your eye."},
{type:"bold",text:"Step 2: Read for Clarity"},
{type:"p",text:"Read with one question only: does this make sense to someone who isn't you? Flag every sentence where a reader might need to re-read to understand. Flag every assumption you make that isn't shared knowledge. Flag every transition that requires the reader to make a leap you haven't bridged."},
{type:"bold",text:"Step 3: Run the Clarity Check Prompt"},
{type:"p",text:"For flagged sections, ask AI: 'Read this as someone intelligent but unfamiliar with my field. Identify any sentences or transitions where clarity breaks down.' Use its feedback to simplify, not to add. Clarity almost always comes from removal, not addition."},
{type:"compare",pairs:[
{weak:"Revising endlessly to avoid publishing.",strong:"One focused clarity pass, then done. Imperfect published beats perfect unpublished."},
]},
{type:"pull",text:"The rule: one clarity pass, one polish pass, done. Every pass after that is fear talking."},
]
},
{ id:"byb-16", course:"byb", title:"Publishing & Beyond", subtitle:"Manuscript to Published Book", tier:"paid", chapter:"PHASE 4: INTEGRATION & POLISH", readTime:"7 min", icon:"🚀", color:"#34d399",
content:[
{type:"p",text:"You've written a book. That's a huge accomplishment — most people who say they're going to write a book never finish. You're not most people. Now the question is: what happens next?"},
{type:"pull",text:"A finished manuscript and a published book are two different things. This chapter closes the gap."},
{type:"bold",text:"Your Publication Options"},
{type:"glossary",terms:[
{word:"Traditional Publishing",definition:"Submit to agents, wait for offers, sign with a publisher. Long timeline (often 2+ years to publication), less control, higher credibility in certain markets."},
{word:"Self-Publishing",definition:"Direct to market via Amazon KDP, IngramSpark, or similar. Full control, higher royalties, faster timeline, requires you to handle design and marketing."},
{word:"Hybrid Publishing",definition:"Pay a publisher to handle production and distribution while retaining more rights than traditional. Faster than traditional, more support than pure self-publishing."},
]},
{type:"bold",text:"Your Pre-Launch Checklist"},
{type:"examples",items:["Cover design: Do not skip this. Readers absolutely judge books by covers. Hire a professional.","ISBN and metadata: Your book's discoverability depends on accurate, keyword-rich metadata.","Beta readers: Get 3–5 people who represent your target reader to read and give feedback before launch.","Launch plan: Who are the first 10 people you'll tell personally? Start there."]},
{type:"bold",text:"Using Your AI Twin to Market the Book"},
{type:"p",text:"Your custom instructions work for marketing content too. Use them to write launch emails, social posts, and promotional copy that sounds like you — consistent with the book's voice, not like generic marketing language."},
{type:"pull",text:"You didn't write this book for it to sit on your hard drive. Get it out. Your readers are waiting for exactly what only you could have written."},
]
},

// ─── COURSE 3: PROMPTING MASTERY ─────────────────────────────────────────────
{ id:"pm-1", course:"prompting", title:"Why Most Prompts Fail", subtitle:"The Gap Between What You Type and What You Mean", tier:"free", chapter:"FOUNDATIONS", readTime:"5 min", icon:"⚡", color:"#fbbf24",
content:[
{type:"p",text:"You type a request. You get something back that's almost right — technically correct, completely soulless. You tweak the wording. Try again. Slightly better. Still not it. You wonder if AI is just overhyped."},
{type:"pull",text:"AI didn't fail you. Your prompt didn't carry enough information to succeed."},
{type:"p",text:"This is the central problem with prompting. Not that AI is bad at things — it's remarkably capable. The problem is that most people treat prompts like search queries. A search query is a question aimed at an index. A prompt is a brief aimed at a collaborator."},
{type:"bold",text:"The Three Gaps"},
{type:"examples",items:[
"The Context Gap: AI doesn't know who you are, what you're building, who it's for, or what success looks like. You do. It doesn't — unless you say.",
"The Format Gap: AI will choose its own structure if you don't specify one. Its default isn't your default. Specify length, tone, format, voice every time.",
"The Permission Gap: AI is trained to be safe and general. If you don't give it explicit permission to be specific, bold, or unconventional — it won't be.",
]},
{type:"p",text:"Every failed prompt is missing information in one of these three places. Once you can diagnose which gap you're dealing with, you can fix any prompt in one edit."},
{type:"pull",text:"A prompt is a brief. Write it like one."},
{type:"bold",text:"The One-Edit Fix"},
{type:"p",text:"Before you rewrite a failed prompt from scratch — diagnose it first. Ask: did it fail because AI didn't know enough about the situation? Did it return the wrong format? Did it play it too safe? That answer tells you exactly what single thing to add. One targeted addition beats a completely rewritten prompt nine times out of ten."},
]
},
{ id:"pm-2", course:"prompting", title:"The Anatomy of a Strong Prompt", subtitle:"Every Part Has a Job", tier:"free", chapter:"FOUNDATIONS", readTime:"6 min", icon:"🔬", color:"#a78bfa",
content:[
{type:"p",text:"Strong prompts aren't longer — they're more complete. There's a difference. You can write 400 words of background that still leaves AI guessing, or you can write 40 words that give it everything it needs. Completeness is about the right information, not more information."},
{type:"pull",text:"Five elements. Every strong prompt has all five."},
{type:"bold",text:"The Five Elements"},
{type:"glossary",terms:[
{word:"Role",definition:"Who AI is being. 'You are a senior UX researcher' is a role. It loads context, expertise, tone, and judgment in one line. Never skip this."},
{word:"Context",definition:"What's happening and why. The situation, the stakes, the background. What you'd tell a new colleague before handing them the task."},
{word:"Task",definition:"What specifically to produce. One action verb, one output. Write. Analyse. Rewrite. Compare. Not 'help me with' — that's too vague."},
{word:"Format",definition:"The shape of the output. Length, structure, tone, language level, whether to use headers or paragraphs, numbered or bulleted."},
{word:"Constraints",definition:"What not to do. What to avoid. Limits that focus the output. 'No jargon. Under 200 words. Don't offer solutions — only identify problems.'"},
]},
{type:"p",text:"Most prompts have two or three of these. Strong prompts have all five. The ones people skip most often: Role (they feel awkward assigning a persona) and Constraints (they forget to say what they don't want)."},
{type:"pull",text:"What you don't want is just as important as what you do."},
{type:"bold",text:"One-Line Versions of Each"},
{type:"examples",items:[
"Role: 'You are a plain-language legal writer who explains complex documents to non-lawyers.'",
"Context: 'I'm building a landing page for a product that helps solo founders manage their finances. The reader is time-poor and skeptical.'",
"Task: 'Write three headline options for the hero section.'",
"Format: 'Each headline: under 10 words. Conversational tone. No exclamation marks.'",
"Constraints: 'Don't mention the word dashboard. Avoid financial jargon. No feature lists — only outcomes.'",
]},
]
},
{ id:"pm-3", course:"prompting", title:"Roles and Personas", subtitle:"The Fastest Way to Upgrade Any Output", tier:"paid", chapter:"TECHNIQUES", readTime:"5 min", icon:"🎭", color:"#f472b6",
content:[
{type:"p",text:"The single fastest upgrade you can make to any prompt is adding a role. One sentence that tells AI who it's being completely changes the knowledge base it draws from, the tone it adopts, the assumptions it makes, and the judgment it applies."},
{type:"pull",text:"'You are a…' — three words that change everything."},
{type:"p",text:"When you don't assign a role, AI picks one by default. It usually picks something generic: a helpful assistant, a general writer, a neutral explainer. Generic roles return generic outputs. Specific roles return specific, expert-level thinking."},
{type:"bold",text:"How to Write a Strong Role"},
{type:"examples",items:[
"Weak: 'You are a writer.' — Too broad. What kind? What expertise? What sensibility?",
"Strong: 'You are a copywriter who specialises in D2C brands with a dry, minimalist voice. You think in headlines first and prose second.'",
"Weak: 'You are an expert.' — Expert in what? For whom?",
"Strong: 'You are a principal engineer who's led three $10M+ SaaS migrations. You explain complex systems to non-technical stakeholders without condescending.'",
]},
{type:"pull",text:"The more specific the role, the more it loads expertise, judgment and sensibility in a single line."},
{type:"bold",text:"Stack Roles for Complex Tasks"},
{type:"p",text:"For tasks that require multiple perspectives, you can stack roles. 'You are a product manager who thinks like a designer and writes like a journalist.' Each element loads a different layer of thinking. Use this sparingly — one precise role beats three vague ones — but for genuinely multi-disciplinary tasks it's a powerful move."},
{type:"bold",text:"Roles vs. Characters"},
{type:"p",text:"A role is expertise. A character is personality. 'You are a Stoic philosopher' is a character — it loads a worldview, a tone, a set of reference points. Both work. Roles are better for task-based outputs; characters are better for voice, perspective, and creative work."},
]
},
{ id:"pm-4", course:"prompting", title:"Chain of Thought Prompting", subtitle:"Making AI Show Its Work", tier:"paid", chapter:"TECHNIQUES", readTime:"6 min", icon:"🔗", color:"#34d399",
content:[
{type:"p",text:"AI is better at reasoning when it reasons out loud. This sounds like a strange thing to say about a machine, but it's consistently true and well-documented. When you ask AI to think step by step before arriving at a conclusion, the conclusion is almost always better."},
{type:"pull",text:"'Think step by step' is one of the highest-leverage additions to any analytical prompt."},
{type:"bold",text:"Why It Works"},
{type:"p",text:"When AI generates text, each word is influenced by what came before it. When it reasons aloud, the reasoning itself becomes context for the conclusion — which means the conclusion has more to draw on. It's not magic. It's the same reason humans think better out loud than they do silently."},
{type:"bold",text:"Three Ways to Trigger It"},
{type:"glossary",terms:[
{word:"Explicit instruction",definition:"'Think through this step by step before giving me your answer.' Direct, always works."},
{word:"Structured output",definition:"'First: identify the core problem. Second: list three possible approaches. Third: recommend one and explain why.' Forces reasoning through the structure."},
{word:"Draft-then-refine",definition:"'Write a rough answer first, then review it and write a final version.' Makes AI critique its own first attempt."},
]},
{type:"bold",text:"When to Use It"},
{type:"examples",items:[
"Any decision or recommendation where the reasoning matters as much as the conclusion.",
"Complex analysis where you suspect AI might jump to a surface answer.",
"Creative problems where you want to see the options considered before the choice.",
"Debugging — asking AI to trace a problem step by step surfaces things a direct 'fix this' misses.",
]},
{type:"pull",text:"The output isn't just better — you can see where the thinking went. That's how you catch errors."},
{type:"p",text:"One caution: chain of thought prompting produces longer outputs. For simple tasks, it's unnecessary overhead. Use it when complexity genuinely warrants it — not as a default for every prompt."},
]
},
{ id:"pm-5", course:"prompting", title:"Few-Shot Prompting", subtitle:"Examples Are Worth a Thousand Instructions", tier:"paid", chapter:"TECHNIQUES", readTime:"5 min", icon:"📐", color:"#60a5fa",
content:[
{type:"p",text:"Telling AI what you want is one approach. Showing it is better. This is the core principle behind few-shot prompting — instead of writing a long description of the desired output, you provide one or more examples of it. AI extracts the pattern and matches it."},
{type:"pull",text:"One good example beats three paragraphs of explanation."},
{type:"bold",text:"Zero, One, and Few"},
{type:"glossary",terms:[
{word:"Zero-shot",definition:"No examples. Just instructions. Works for straightforward tasks, often fails for specific style, format, or tone requirements."},
{word:"One-shot",definition:"One example provided. Dramatic improvement over zero-shot for most tasks. The example sets a clear target."},
{word:"Few-shot",definition:"Two to five examples. Each additional example narrows the target further and reduces variance in outputs."},
]},
{type:"bold",text:"What Makes a Good Example"},
{type:"examples",items:[
"It should represent the output you want, not a rough version of it. AI will match the quality of your example.",
"It should be real, not fabricated. Use actual examples of writing you admire, actual product copy you think works, actual headlines that hit.",
"For tone and voice tasks: use your own previous work. It's the most direct way to train a session on your style.",
"Label your examples clearly: 'Here is an example of what I mean:' followed by the example, then your actual request.",
]},
{type:"pull",text:"AI's output quality ceiling is set by the quality of your examples."},
{type:"bold",text:"Negative Examples"},
{type:"p",text:"You can also show AI what you don't want. 'Here's an example of the tone I'm trying to avoid:' followed by the bad example. Negative examples are particularly useful when the failure mode is subtle — when the difference between good and mediocre is hard to describe but easy to recognise."},
]
},
{ id:"pm-6", course:"prompting", title:"Iteration and Refinement", subtitle:"Your First Prompt Is a Draft", tier:"paid", chapter:"TECHNIQUES", readTime:"5 min", icon:"🔄", color:"#fb923c",
content:[
{type:"p",text:"The best prompters in the world don't write perfect prompts first time. They write useful first drafts and refine deliberately. The goal of your first prompt isn't to get the final output — it's to get something you can react to."},
{type:"pull",text:"Treat the first output as a mirror, not a deliverable."},
{type:"bold",text:"The Refinement Loop"},
{type:"examples",items:[
"Prompt → Output → Diagnose what's off → Add one specific instruction → Repeat.",
"Never rewrite the whole prompt when one targeted addition will fix it.",
"If the output is 70% right, tell AI exactly what the 30% needs to become. 'The structure is right. The tone is too formal — rewrite it like you're talking to a friend who happens to be smart.'",
"Use the conversation history. You don't have to start from scratch every time. 'Keep everything except the third paragraph — rewrite that to be more specific.'",
]},
{type:"bold",text:"Three Types of Refinement"},
{type:"glossary",terms:[
{word:"Scope refinement",definition:"The output got the direction right but went too broad or too narrow. 'Focus only on the first problem you raised, and go deeper.'"},
{word:"Tone refinement",definition:"The content is right but the voice is off. 'Same content, warmer tone. Less corporate.' Or: 'More direct. Cut the softening language.'"},
{word:"Format refinement",definition:"The ideas are there but the structure makes them hard to use. 'Convert this to a numbered list.' Or: 'Turn this into a short paragraph instead.'"},
]},
{type:"pull",text:"Prompting is a conversation, not a vending machine. Use the full conversation."},
]
},
{ id:"pm-7", course:"prompting", title:"Prompt Templates", subtitle:"Build Once, Use Forever", tier:"paid", chapter:"ADVANCED", readTime:"6 min", icon:"📋", color:"#e8e4d9",
content:[
{type:"p",text:"Once you find a prompt structure that works, template it. A prompt template is a proven structure with placeholder variables — the reusable parts stay fixed, you swap in the specifics each time. This is how people who use AI heavily stay consistent and fast."},
{type:"pull",text:"Your best prompt today is your template for tomorrow."},
{type:"bold",text:"Anatomy of a Template"},
{type:"p",text:"A template has three kinds of content: fixed text that never changes (your role definition, your formatting requirements, your quality standards), variable slots marked with brackets like [TOPIC] or [AUDIENCE], and optional sections you include or exclude based on the task."},
{type:"bold",text:"A Working Example"},
{type:"examples",items:[
"ROLE: You are a senior [INDUSTRY] strategist who communicates with precision and zero jargon.",
"CONTEXT: I'm preparing [DELIVERABLE TYPE] for [AUDIENCE]. They care most about [THEIR PRIORITY].",
"TASK: [SPECIFIC ACTION VERB] the following: [INPUT]",
"FORMAT: [LENGTH]. [STRUCTURE PREFERENCE]. [TONE].",
"AVOID: [WHAT NOT TO DO].",
]},
{type:"pull",text:"A library of 10 strong templates beats ad-hoc prompting every single time."},
{type:"bold",text:"Where to Keep Them"},
{type:"p",text:"The Codex inside Wizards Playground is built for this. Save your best prompts there, categorised by use case. A well-maintained Codex is genuinely one of the most valuable things you can build as an AI practitioner — your personal spell library that compounds over time."},
]
},
{ id:"pm-8", course:"prompting", title:"Prompting for Creativity", subtitle:"Unlocking Unexpected Output", tier:"paid", chapter:"ADVANCED", readTime:"6 min", icon:"✨", color:"#c084fc",
content:[
{type:"p",text:"Most prompting guides are written for analytical tasks — research, summarisation, drafting structured documents. Creative prompting works differently. The goal isn't precision and accuracy — it's controlled surprise. You want something that feels discovered, not produced."},
{type:"pull",text:"The creative prompt is an invitation, not a specification."},
{type:"bold",text:"The Permission Layer Is Everything"},
{type:"p",text:"AI defaults to safe, expected, conventional outputs — especially for creative work. The single most important thing you can do in a creative prompt is give explicit permission to be unexpected. 'Surprise me.' 'Give me the version you'd actually want to read.' 'Subvert the obvious interpretation.' These phrases do real work."},
{type:"bold",text:"Techniques for Creative Prompts"},
{type:"glossary",terms:[
{word:"The oblique angle",definition:"Don't ask for the thing directly. Ask for something adjacent that implies it. Instead of 'write a poem about grief', try 'write a poem told from the perspective of an empty chair at a family table'."},
{word:"The constraint paradox",definition:"Tight constraints often produce more creative output than open briefs. 'Write this in exactly 50 words' or 'use only one-syllable words' forces unexpected solutions."},
{word:"The temperature instruction",definition:"Explicitly tell AI to take risks. 'Give me the unusual version.' 'What would this look like if you ignored the obvious approach?' 'Write the version that might not work but is interesting.'"},
]},
{type:"pull",text:"Constraints liberate. The narrow gate opens into a wider space than the open field."},
{type:"bold",text:"Iterating Creatively"},
{type:"p",text:"In creative work, the first output is almost never the answer — it's the start of a conversation. 'I like this element and this one. The middle isn't working. Take those two things and go further.' Creative iteration isn't refinement — it's escalation. You're not correcting toward a known target. You're discovering what the target is."},
]
},
{ id:"pm-9", course:"prompting", title:"Context Windows Explained", subtitle:"Working With AI's Memory", tier:"paid", chapter:"ADVANCED", readTime:"5 min", icon:"🧠", color:"#34d399",
content:[
{type:"p",text:"Every AI model has a context window — the amount of text it can hold in its working memory at one time. Everything you type, everything it types back, any documents you paste in — all of it sits inside this window. When the window is full, the oldest content falls out. Understanding this changes how you prompt."},
{type:"pull",text:"AI doesn't remember your last conversation. It only knows what's in the window right now."},
{type:"bold",text:"What This Means in Practice"},
{type:"examples",items:[
"Long conversations drift. If you've been working on something for an hour, your original instructions might be far up the thread — too far for AI to weight heavily. Re-anchor important instructions mid-conversation.",
"Pasting large documents eats context. If you paste a 20,000-word document, you've used most of a typical context window before you've asked anything.",
"AI can't remember across sessions by default. Each new conversation starts fresh. Any context you need has to be re-established.",
"The start and end of the context window get the most weight. Important instructions go at the top or the bottom of your prompt — not buried in the middle.",
]},
{type:"bold",text:"Key Terms"},
{type:"glossary",terms:[
{word:"Context Window",definition:"The total amount of text an AI model can process at once, measured in tokens. Ranges from a few thousand to hundreds of thousands depending on the model."},
{word:"Token",definition:"Roughly 3/4 of a word in English. 'Context window' = 2 tokens. 100,000 tokens ≈ 75,000 words — about a full novel."},
{word:"Lost in the Middle",definition:"A documented phenomenon where AI gives less weight to information in the middle of a long context. Front-load your most important instructions."},
]},
{type:"pull",text:"Treat every prompt as if AI has just woken up and knows nothing. Give it what it needs, every time."},
]
},
{ id:"pm-10", course:"prompting", title:"The Prompting Glossary", subtitle:"Every Term You Need to Know", tier:"paid", chapter:"ADVANCED", readTime:"7 min", icon:"📖", color:"#fbbf24",
content:[
{type:"p",text:"Prompting has developed its own vocabulary fast. Some terms matter practically — knowing them will change how you work. Others are useful for navigating conversations about AI. Here's the complete reference."},
{type:"pull",text:"You don't need to memorise all of this. You need to know it exists so you can look it up."},
{type:"glossary",terms:[
{word:"Prompt",definition:"The input you give an AI model. Can be a question, instruction, example, or any combination. Everything before the AI responds."},
{word:"System Prompt",definition:"Instructions given to an AI before the conversation starts, often invisible to the user. Sets the AI's role, behaviour, and constraints for the entire session."},
{word:"Zero-shot",definition:"Prompting with no examples — just an instruction. Works for common tasks; struggles with specific style or format requirements."},
{word:"Few-shot",definition:"Prompting with one or more examples included. Dramatically improves output quality for style, tone, and format-specific tasks."},
{word:"Chain of Thought",definition:"Prompting technique where you instruct AI to reason step by step before concluding. Improves accuracy on analytical and multi-step problems."},
{word:"Temperature",definition:"A setting that controls how 'creative' or 'random' AI output is. High temperature = more varied, surprising outputs. Low temperature = more predictable, conservative outputs. Not visible in most consumer tools."},
{word:"Hallucination",definition:"When AI confidently produces factually incorrect information. More common when asking for specific facts, statistics, or citations. Always verify factual claims independently."},
{word:"Prompt Injection",definition:"An attack where malicious text embedded in content tries to hijack AI's behaviour. Mostly a concern for developers building AI products, not consumer users."},
{word:"RAG (Retrieval-Augmented Generation)",definition:"A technique where AI retrieves relevant information from an external database before responding. The mechanism behind most 'AI search' products."},
{word:"Fine-tuning",definition:"Training a model on a specific dataset to specialise its behaviour. Different from prompting — it changes the model itself, not just its instructions for a session."},
{word:"Grounding",definition:"Giving AI real, specific, current information to respond from — as opposed to relying on its training data. Pasting a document for AI to summarise is a form of grounding."},
{word:"Latency",definition:"The time between sending a prompt and receiving a response. Varies by model size and API load."},
{word:"Token limit",definition:"The maximum input and output size a model supports. If your prompt plus expected response exceeds this, the model will truncate."},
]},
{type:"pull",text:"The goal isn't fluency in AI jargon. It's knowing enough to work effectively and call out nonsense when you hear it."},
]
},

// ─── COURSE 4: DEMYSTIFY AI ───────────────────────────────────────────────────
{ id:"dai-1", course:"demystify", title:"What AI Actually Is", subtitle:"Strip Away the Hype and the Fear", tier:"free", chapter:"WHAT IS IT", readTime:"6 min", icon:"🌐", color:"#60a5fa",
content:[
{type:"p",text:"Artificial intelligence is one of the most hyped and most misunderstood technologies in human history — simultaneously. The hype says it's going to do everything. The fear says it's going to end everything. The reality is more interesting and more specific than either."},
{type:"pull",text:"AI is a tool built from patterns. Powerful. Not magic. Not sentient. Not inevitable in any particular direction."},
{type:"p",text:"The AI tools you interact with today — ChatGPT, Claude, Gemini, Midjourney — are mostly built on a class of technology called large language models. They're not intelligent in the way humans are intelligent. They don't understand, believe, feel, or experience. They predict. Extremely sophisticated, trained-on-almost-everything prediction."},
{type:"bold",text:"What AI Is Actually Doing"},
{type:"p",text:"When you type a prompt and AI responds, what's happening is: the model has been trained on an enormous amount of text. It has learned statistical patterns — which words follow which other words in which contexts. When you give it input, it generates output by predicting what text would most plausibly come next given everything it knows. Token by token. Word by word."},
{type:"pull",text:"It's not thinking. It's predicting at a scale and fidelity that can look a lot like thinking."},
{type:"bold",text:"What That Means for You"},
{type:"examples",items:[
"AI is not looking up answers — it's generating them. Which is why it can be confidently wrong.",
"AI has no goals, no preferences, no desire to deceive you. It doesn't have any inner life at all. Outputs that seem emotional or opinionated are patterns, not feelings.",
"AI is not one thing. Different models, different training data, different design choices produce wildly different capabilities and behaviours.",
"The more you understand about how it works, the better you'll use it — and the less its failures will surprise you.",
]},
]
},
{ id:"dai-2", course:"demystify", title:"How Large Language Models Learn", subtitle:"Training, Data, and Why That Matters", tier:"free", chapter:"WHAT IS IT", readTime:"7 min", icon:"📊", color:"#a78bfa",
content:[
{type:"p",text:"A large language model doesn't come pre-loaded with answers. It learns by reading — reading more text than any human could read in thousands of lifetimes, and learning the patterns within it. Understanding how this works explains most of what AI does well and most of what it gets wrong."},
{type:"pull",text:"The model is only as good as what it was trained on — and what it was trained on is everything and nothing."},
{type:"bold",text:"The Training Process"},
{type:"p",text:"Training has two main phases. In pre-training, the model reads enormous amounts of text — web pages, books, code, scientific papers, conversations — and learns to predict what comes next. This builds its foundational knowledge. Then in fine-tuning, humans provide feedback on what good responses look like, steering the model toward outputs that are helpful, accurate, and safe."},
{type:"glossary",terms:[
{word:"Pre-training",definition:"The phase where the model reads vast amounts of text and learns statistical patterns. Builds general knowledge and language capability."},
{word:"Fine-tuning / RLHF",definition:"Reinforcement Learning from Human Feedback. Humans rate AI outputs, and the model learns to produce outputs humans rate highly. This is what makes a raw language model into a useful assistant."},
{word:"Training data",definition:"The text the model learned from. Quality, diversity, and recency of training data directly affects capability. Most models have a knowledge cutoff — a point after which they have no information."},
{word:"Parameters",definition:"The numerical values inside the model that encode what it has learned. 'GPT-4 has 1.7 trillion parameters' means 1.7 trillion individual values tuned during training. More parameters generally means more capability and more cost."},
]},
{type:"pull",text:"'The AI said it' doesn't mean it's true. It means it's a plausible-sounding continuation of the prompt you gave."},
{type:"bold",text:"What This Means in Practice"},
{type:"p",text:"Because AI learned from human-generated text, it reflects human knowledge — including human biases, human errors, and human gaps. It can perpetuate stereotypes present in training data. It has more knowledge about topics that have more text written about them. It knows less about recent events than older ones. These aren't bugs being fixed — they're structural features of how the technology works."},
]
},
{ id:"dai-3", course:"demystify", title:"Hallucinations and Why AI Lies", subtitle:"Confident, Wrong, and Not Sorry About It", tier:"paid", chapter:"LIMITATIONS", readTime:"5 min", icon:"👻", color:"#f472b6",
content:[
{type:"p",text:"Hallucination is the AI industry's polite word for something more alarming: AI confidently making things up. Not guessing. Not hedging. Stating fabricated information with the same authority it would use for accurate information. Understanding why this happens is one of the most important things you can learn about working with AI."},
{type:"pull",text:"AI doesn't know what it doesn't know. It generates plausible text — and plausible is not the same as true."},
{type:"bold",text:"Why It Happens"},
{type:"p",text:"Remember: AI is predicting the most plausible next text given its training. When you ask for a specific fact — a citation, a statistic, a person's biography — AI doesn't retrieve it from a database. It generates what a plausible-sounding answer would look like. Sometimes that matches reality. Sometimes it's entirely fabricated. AI can't always tell the difference, and more importantly, it doesn't tell you when it can't."},
{type:"bold",text:"Where Hallucinations Are Most Common"},
{type:"examples",items:[
"Specific citations and academic references — AI will generate plausible-sounding papers that don't exist.",
"Statistics and numbers — percentages, dates, quantities are frequently fabricated.",
"Biographies of real but non-famous people — AI fills gaps with invention.",
"Events near or after its training cutoff — it has less data, more to invent.",
"Niche technical details — the more specialised the domain, the less training data, the more gaps.",
]},
{type:"pull",text:"Use AI to think. Verify facts independently. Always."},
{type:"bold",text:"How to Reduce Them"},
{type:"p",text:"Ask AI to say 'I don't know' when it's uncertain — it will comply more often than you'd expect. Ask it to show its reasoning, not just its conclusion. For anything that matters, verify it with a primary source. Treat AI output as a strong first draft, not a finished fact. The question 'how confident are you in this?' produces more honest and useful responses than accepting everything at face value."},
]
},
{ id:"dai-4", course:"demystify", title:"AI Models Compared", subtitle:"GPT vs Claude vs Gemini vs the Rest", tier:"paid", chapter:"LIMITATIONS", readTime:"6 min", icon:"⚖️", color:"#34d399",
content:[
{type:"p",text:"'AI' isn't one thing. There are dozens of serious AI models available today, each with different training data, different design philosophies, different strengths, and different failure modes. Knowing the broad differences helps you use the right tool for the right job."},
{type:"pull",text:"The best model is the one that's best at what you're trying to do right now."},
{type:"bold",text:"The Major Players"},
{type:"glossary",terms:[
{word:"GPT-4 / ChatGPT (OpenAI)",definition:"The model that brought AI to mainstream attention. Strong across most tasks. Massive plugin and integration ecosystem. ChatGPT is the consumer product; GPT-4 is the underlying model available via API."},
{word:"Claude (Anthropic)",definition:"Designed with a strong emphasis on safety, honesty, and nuanced reasoning. Particularly strong at long documents, careful analysis, and tasks where being wrong has consequences. Generally more conservative than GPT."},
{word:"Gemini (Google)",definition:"Google's model family. Deeply integrated with Google's product ecosystem. Strong at tasks involving real-time web search and Google Workspace data."},
{word:"Llama (Meta)",definition:"An open-source model family that can be downloaded and run locally. No API costs, full privacy — but requires technical setup and hardware."},
{word:"Mistral",definition:"A European open-source model. Notably efficient — strong performance relative to its size. Popular with developers who need to run models cheaply."},
]},
{type:"bold",text:"How to Choose"},
{type:"examples",items:[
"For most everyday tasks: any of the top-tier models work. Try one, switch if it's not clicking.",
"For long documents (contracts, reports, books): Claude handles very long contexts particularly well.",
"For real-time information: Gemini with Search or ChatGPT with web browsing.",
"For coding: all major models are strong. GPT-4 and Claude both excel. Try both on your specific stack.",
"For privacy-sensitive work: local models (Llama, Mistral) keep your data off external servers.",
]},
{type:"pull",text:"Model loyalty is marketing. Capability is task-specific. The best prompters use multiple tools."},
]
},
{ id:"dai-5", course:"demystify", title:"AI Safety and Alignment", subtitle:"What the Experts Are Actually Worried About", tier:"paid", chapter:"THE BIGGER PICTURE", readTime:"7 min", icon:"🛡", color:"#fbbf24",
content:[
{type:"p",text:"AI safety has become one of the most discussed topics in technology — and one of the most distorted. Pop culture gives us Terminator. Social media gives us either panic or dismissal. Neither is useful. Here's what the actual researchers working on this problem are thinking about."},
{type:"pull",text:"The serious AI safety concerns aren't about robots. They're about systems that optimise for the wrong thing."},
{type:"bold",text:"Alignment: The Core Problem"},
{type:"p",text:"Alignment is the problem of making AI systems that reliably do what humans actually want — not just what humans literally said. These are different. A paperclip factory optimising for paperclip production that converts all available matter into paperclips is doing exactly what it was told. It's not aligned with what humans wanted. This sounds absurd at small scale; at the scale of a sufficiently capable AI system, it stops being absurd."},
{type:"glossary",terms:[
{word:"Alignment",definition:"The goal of ensuring AI systems pursue objectives that match human values and intentions, not just the literal instructions they were given."},
{word:"RLHF (Reinforcement Learning from Human Feedback)",definition:"The main current technique for alignment. Humans rate AI outputs, the model learns to produce outputs humans rate highly. Works reasonably well at current scales; questions remain about how it scales."},
{word:"Instrumental convergence",definition:"The observation that many different AI goals lead to similar intermediate behaviours — like acquiring resources and preventing shutdown — regardless of the final goal. A system trying to do anything tends to want to keep existing."},
{word:"Existential risk",definition:"The possibility that a sufficiently advanced misaligned AI could cause permanent, civilisation-scale harm. A minority of serious researchers consider this the dominant risk; the majority focus on nearer-term harms."},
]},
{type:"bold",text:"The Near-Term Concerns That Matter More Right Now"},
{type:"examples",items:[
"Misinformation at scale — AI makes it cheap to produce convincing false content.",
"Automation displacement — some jobs will be eliminated or transformed faster than workers can adapt.",
"Concentration of power — powerful AI capabilities concentrated in a few companies or governments.",
"Bias amplification — AI systems encoding and scaling the biases present in their training data.",
]},
{type:"pull",text:"You don't have to choose between 'AI will be fine' and 'AI will destroy us.' The space between those is where the important work is."},
]
},
{ id:"dai-6", course:"demystify", title:"AI and Creative Work", subtitle:"Threat, Tool, or Something Else?", tier:"paid", chapter:"THE BIGGER PICTURE", readTime:"6 min", icon:"🎨", color:"#fb923c",
content:[
{type:"p",text:"No question about AI provokes more anxiety in creative communities than this one: is it going to replace us? The honest answer is: it depends on what 'us' means, and it requires separating what AI can do from what creativity actually is."},
{type:"pull",text:"AI can produce. It cannot intend. And intention is most of what makes art matter."},
{type:"bold",text:"What AI Can Do in Creative Work"},
{type:"examples",items:[
"Generate large volumes of content quickly — first drafts, variations, alternatives.",
"Match styles and formats with high fidelity when given good examples.",
"Remove friction from execution so more time goes to decisions about what to make.",
"Suggest directions you might not have considered.",
"Handle the functional parts of creative work — the descriptions, the metadata, the summaries — so humans can focus on the irreducible parts.",
]},
{type:"bold",text:"What AI Cannot Do"},
{type:"p",text:"AI has no stakes. It doesn't care what it makes. It can produce a poem about grief without having lost anything. It can write a love scene without having loved anyone. For a lot of commercial creative work, this doesn't matter — the output is judged on its effect, not its origin. For art that matters, it's the whole question."},
{type:"pull",text:"The market for technically competent generic content will compress. The market for distinctly human perspective will not."},
{type:"bold",text:"The Actual Shift"},
{type:"p",text:"What's changing isn't whether humans will make creative work — it's which humans and in what volume. The bottleneck used to be execution: could you draw, could you write, could you design? That bottleneck is lowering fast. The new bottleneck is vision, taste, and perspective: do you have something specific to say, and do you know when the work is right? Those have always been the hard parts. They're about to become the only parts that matter."},
]
},
{ id:"dai-7", course:"demystify", title:"The Ethics of AI", subtitle:"Questions Worth Asking Before You Hit Send", tier:"paid", chapter:"THE BIGGER PICTURE", readTime:"6 min", icon:"⚖️", color:"#e8e4d9",
content:[
{type:"p",text:"Using AI involves ethical choices — some obvious, some subtle, most people don't think about until something goes wrong. This isn't a lecture. It's a map of the questions worth having thought through before they become problems."},
{type:"pull",text:"The question isn't whether AI raises ethical issues. It's which ones apply to what you're doing."},
{type:"bold",text:"The Questions Worth Asking"},
{type:"glossary",terms:[
{word:"Disclosure",definition:"When should you tell people you used AI? There's no universal answer. In academic work, usually always. In commercial content, depends on context and platform rules. In personal writing, your call. Have a position."},
{word:"Data and privacy",definition:"What are you feeding into AI tools? Customer data, confidential business information, and private personal details all carry risks when submitted to external AI services. Know your provider's data policies."},
{word:"Training data and consent",definition:"Most AI models were trained on human-created content without the creators' explicit consent. This is actively contested legally and ethically. Using these tools makes you a participant in that debate."},
{word:"Bias and representation",definition:"AI systems encode the biases of their training data. Outputs can reinforce stereotypes about race, gender, geography, and culture. Being aware of this doesn't solve it — but unawareness compounds it."},
{word:"Environmental cost",definition:"Training large AI models and running them at scale has significant energy cost. This isn't a reason not to use them — it's a reason to be honest about the tradeoffs."},
]},
{type:"bold",text:"A Useful Framing"},
{type:"p",text:"Think of it like driving. Cars cause enormous harm — accidents, emissions, urban sprawl. They also provide enormous value. Most people don't resolve this by either never driving or ignoring the harms. They drive thoughtfully, support infrastructure that reduces harms, and stay engaged with the societal conversation about the tradeoffs. That's roughly the right posture toward AI."},
{type:"pull",text:"Engagement with these questions is more useful than either guilt or indifference."},
]
},
{ id:"dai-8", course:"demystify", title:"Where AI Is Going", subtitle:"What's Real, What's Hype, What to Watch", tier:"paid", chapter:"THE BIGGER PICTURE", readTime:"6 min", icon:"🔭", color:"#a78bfa",
content:[
{type:"p",text:"Predicting AI development is a fool's game — the field has surprised experts repeatedly in both directions, faster than expected and slower than expected at different things. What you can do is understand the credible directions, distinguish them from hype, and know what to watch."},
{type:"pull",text:"The question is not 'what will AI be able to do' — it's 'what will matter when it can do those things'."},
{type:"bold",text:"What's Genuinely Coming"},
{type:"examples",items:[
"Multimodal models that work across text, image, audio, and video simultaneously are already here and improving fast.",
"AI agents — systems that take sequences of actions, not just respond to one prompt — are in early deployment and will become increasingly capable.",
"Personalisation — models that know more about you and tailor to your specific context — is technically straightforward and commercially inevitable.",
"Lower costs — running AI is getting cheaper rapidly, which means more access and more competition.",
]},
{type:"bold",text:"What's Still Genuinely Uncertain"},
{type:"glossary",terms:[
{word:"AGI (Artificial General Intelligence)",definition:"AI that can perform any intellectual task a human can. No one has it. Timeline estimates range from 5 years to never, depending on who you ask. Treat claims about imminent AGI with scepticism."},
{word:"Reasoning",definition:"Current models produce outputs that look like reasoning but may not be genuine step-by-step logical inference. Whether AI can truly reason — and whether that distinction matters — is actively debated."},
{word:"Consciousness",definition:"No current AI system is conscious or sentient. Whether a sufficiently advanced system could be is a genuinely open philosophical question. It is not a current practical concern."},
]},
{type:"bold",text:"What to Watch"},
{type:"p",text:"Watch agent capabilities more than model benchmarks. The shift from 'AI that answers questions' to 'AI that takes actions in the world' is the one with the most significant practical and ethical implications. Watch regulatory developments — how governments choose to govern AI will shape its trajectory as much as the technology itself. And watch what skilled humans do with these tools — that's where the real signal is, before the noise of the hype cycle catches up."},
{type:"pull",text:"Stay curious. Stay sceptical. Build your own informed position."},
]
},
];
